[Form]
public class AVAQuotationLookup extends FormRun
{
    AVASalesQuotationQuickCopying  salesQuotationQuickCopying;
}

/// <summary>
///
/// </summary>
public edit KCS_KBVBuildingProjectID editBuildingProjectID(boolean _set, KCS_KBVBuildingProjectID _buildingProjectID)
{
    if (_set)
    {
        salesQuotationQuickCopying.parmBuildingProjectId(_buildingProjectID);   
        element.editQuotationId(true, '');
    }

    return salesQuotationQuickCopying.parmBuildingProjectId();
}

public edit DataAreaId editDataAreaId(boolean     _set, DataAreaId  _dataAreaId)
{
    if (_set)
    {
        salesQuotationQuickCopying.parmFromDataArea(_dataAreaId);
    }

    return  salesQuotationQuickCopying.parmFromDataArea();
}

public edit QuotationIdBase editQuotationId(boolean           _set, QuotationIdBase   _quotationId)
{
    if (_set)
    {
        salesQuotationQuickCopying.parmFromQuotationId(_quotationId);
    }

    return  salesQuotationQuickCopying.parmFromQuotationId();
}

public void init()
{
    if (!element.args().caller())
    {
        throw error("@SYS83964");
    }

    salesQuotationQuickCopying =  element.args().caller().runbase();

    super();

    this.design().caption(salesQuotationQuickCopying.caption());

    editDataAreaId.visible(salesQuotationQuickCopying.parmCopyCrossCompany());

    if(salesQuotationQuickCopying.parmToSalesQuotationTable().KCS_KBVBuildingProjectID)
    {
        element.editBuildingProjectID(true, salesQuotationQuickCopying.parmToSalesQuotationTable().KCS_KBVBuildingProjectID);
    }
}

public void closeOk()
{
    DialogRunbase dialog = element.args().caller();

    dialog.updateServer();

    if (salesQuotationQuickCopying.checkCloseDialog())
    {
        super();
    }
}

public void lookup()
{
    SysTableLookup          sysTableLookup      = SysTableLookup::newParameters(tableNum(SalesQuotationTable), this);
    Query                   query               = new Query();
    QueryBuildDataSource    qbds;

    qbds = query.addDataSource(tableNum(SalesQuotationTable));
    qbds.company(salesQuotationQuickCopying.parmFromDataArea());
    qbds.addRange(fieldNum(SalesQuotationTable, KCS_KBVBuildingProjectID)).value(salesQuotationQuickCopying.parmBuildingProjectId());       
    qbds.addRange(fieldnum(SalesQuotationTable, QuotationId)).value(SysQuery::valueNot(salesQuotationQuickCopying.parmToQuotationId()));

    qbds.addSortField(fieldnum(SalesQuotationTable, QuotationId));

    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, QuotationId), true);
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, QuotationName));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, QuotationStatus));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, KCS_QuotationFirst));               
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, DataAreaId));

    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();

}
